import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"API reference","description":"Two unfiltered plane contracts: openapi.client.json (client and store) and openapi.admin.json (admin and CI). Download them or open Scalar in a new window.","frontmatter":{"title":"API reference","description":"Two unfiltered plane contracts: openapi.client.json (client and store) and openapi.admin.json (admin and CI). Download them or open Scalar in a new window."},"headers":[],"relativePath":"en/api/reference/index.md","filePath":"en/api/reference/index.md","lastUpdated":1790057721000}`),a={name:`en/api/reference/index.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="api-reference" tabindex="-1">API reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to “API reference”">​</a></h1><p>KiriVers exposes two HTTP planes. The docs build copies the same contract files the running process embeds. It does <strong>not</strong> slice them into four filtered specs.</p><table tabindex="0"><thead><tr><th>Plane</th><th>Contract file</th><th>Covers</th></tr></thead><tbody><tr><td>Client</td><td><code>openapi.client.json</code></td><td>Native JSON (check, download, delta, announcements, …) <strong>and</strong> store <code>/store/</code> feeds</td></tr><tr><td>Admin</td><td><code>openapi.admin.json</code></td><td>Console automation <strong>and</strong> CI tokens / <code>ci/releases</code></td></tr></tbody></table><p>Mapping:</p><ul><li><strong>Client / store</strong>: <code>openapi.client.json</code></li><li><strong>Admin / CI</strong>: <code>openapi.admin.json</code></li></ul><p>Each plane’s <code>GET /api/v1/openapi.json</code> and the downloads below come from the same source. Tutorials do not hand-copy field tables.</p><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to “Download”">​</a></h2><ul><li><a href="/openapi/openapi.client.json" download="openapi.client.json"><code>openapi.client.json</code></a></li><li><a href="/openapi/openapi.admin.json" download="openapi.admin.json"><code>openapi.admin.json</code></a></li></ul><h2 id="open-scalar-in-a-new-window" tabindex="-1">Open Scalar in a new window <a class="header-anchor" href="#open-scalar-in-a-new-window" aria-label="Permalink to “Open Scalar in a new window”">​</a></h2><p>Scalar is a full-viewport explorer. It is <strong>not</strong> embedded in a docs page with a sidebar. Open it in a new window:</p><ul><li><a href="/en/api/scalar/client" target="_blank" rel="noopener">Client / store Scalar</a></li><li><a href="/en/api/scalar/admin" target="_blank" rel="noopener">Admin / CI Scalar</a></li></ul><p>Related tutorials: <a href="/en/api/client/">Client HTTP</a>, <a href="/en/api/admin/">Admin automation</a>, <a href="/en/api/ci">CI releases</a>, <a href="/en/api/conventions">Conventions</a>. Error codes: <a href="/en/faq/errors">FAQ</a>.</p>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};